<?php
require_once 'includes/auth.php';require_once 'config/db.php';$page_title='Deposit';$msg='';$err='';
if(isset($_POST['deposit'])){$aid=(int)$_POST['account_id'];$amount=(float)$_POST['amount'];$note=trim($_POST['note']);if($amount<=0)$err='Enter a valid amount.';else{$conn->begin_transaction();try{$s=$conn->prepare("UPDATE accounts SET balance=balance+? WHERE id=? AND status='Active'");$s->bind_param('di',$amount,$aid);$s->execute();if($s->affected_rows!==1)throw new Exception('Account not found.');$t=$conn->prepare("INSERT INTO transactions(account_id,type,amount,note) VALUES(?,'Deposit',?,?)");$t->bind_param('ids',$aid,$amount,$note);$t->execute();$conn->commit();$msg='Deposit completed successfully.';}catch(Exception $e){$conn->rollback();$err=$e->getMessage();}}}
$accounts=$conn->query("SELECT a.id,a.account_no,c.name,a.balance FROM accounts a JOIN customers c ON c.id=a.customer_id WHERE a.status='Active' ORDER BY a.account_no");include 'includes/header.php';?>
<?php if($msg):?><div class="alert alert-success"><?=$msg?></div><?php endif;?><?php if($err):?><div class="alert alert-danger"><?=htmlspecialchars($err)?></div><?php endif;?>
<div class="cardx p-4" style="max-width:760px"><h5>Deposit Money</h5><p class="muted">Add funds to an active bank account.</p><form method="post" class="mt-4"><label class="form-label">Account</label><select class="form-select mb-3" name="account_id" required><option value="">Select account</option><?php while($a=$accounts->fetch_assoc()):?><option value="<?=$a['id']?>"><?=htmlspecialchars($a['account_no'].' - '.$a['name'].' | ₹'.number_format($a['balance'],2))?></option><?php endwhile;?></select><label class="form-label">Amount</label><input class="form-control mb-3" name="amount" type="number" min=".01" step=".01" required><label class="form-label">Note</label><input class="form-control mb-4" name="note" placeholder="Optional note"><button class="btn btn-success px-4" name="deposit"><i class="bi bi-arrow-down-circle me-2"></i>Deposit</button></form></div><?php include 'includes/footer.php';?>
